using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;
using WireMock.RequestBuilders;
using WireMock.ResponseBuilders;
using WireMock.Server;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly WireMockServer provider = WireMockServer.Start();
    private readonly HttpClient client;
    private readonly HttpPaymentGateway sut;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = new Uri(provider.Url!) };
        sut = new HttpPaymentGateway(client);
    }

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        StubResponse(200, """{"status":"approved"}""");

        await sut.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var request = Assert.Single(provider.LogEntries).RequestMessage;
        Assert.Equal("POST", request!.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.Headers!["Content-Type"].Single());
        using var json = JsonDocument.Parse(request.Body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        StubResponse(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        StubResponse(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Unknown_fields_in_the_answer_are_ignored()
    {
        StubResponse(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_refused_payment_is_read_as_declined()
    {
        StubResponse(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_status_the_gateway_does_not_know_is_never_read_as_approved()
    {
        StubResponse(200, """{"status":"pending_review"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_status_is_never_read_as_approved()
    {
        StubResponse(200, """{"decision":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Errors_other_than_a_refusal_surface_as_failures_not_as_declines(int status)
    {
        StubResponse(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_non_json_answer_surfaces_as_a_failure()
    {
        StubResponse(200, "<html>gateway timeout</html>");

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        sut.AuthorizeAsync("ORD-7", new Money(12m, "EUR"), CancellationToken.None);

    private void StubResponse(int status, string body) =>
        provider.Given(Request.Create().WithPath("/v1/authorizations").UsingPost())
            .RespondWith(Response.Create().WithStatusCode(status)
                .WithHeader("Content-Type", "application/json").WithBody(body));

    public void Dispose()
    {
        client.Dispose();
        provider.Stop();
    }
}
EOF
